{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unfolds a map of the ruined royal city.",
      "visual_description": "A windswept hilltop overlooking a shattered skyline of broken towers and torn banners; an ink-stained map flaps in the wind across a flat stone.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of a trap inside the walls.",
      "visual_description": "A battered oil lamp hovers beside the map, its single flame-eye casting a long warning shadow across the parchment.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The tin fox is wound up for scouting.",
      "visual_description": "A small clockwork fox with blue glass eyes sits on the stone while a brass key in its tail turns; gears tick under moonlight.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "The glass diver arrives through a cracked window.",
      "visual_description": "A figure in a clear diving helmet steps out of a broken pane of glass on a ruined wall, coat shimmering with reflected city lights.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "The team approaches the towering castle gates.",
      "visual_description": "Massive iron gates loom over the four companions, half-collapsed, with chains snaking across cracked flagstones.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "The tin fox slips between the bars to scout ahead.",
      "visual_description": "The clockwork fox squeezes between rusted bars, tail-key still ticking, casting a tiny shadow on the courtyard beyond.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "A cursed tower glows green on the horizon.",
      "visual_description": "An impossibly tall tower leans against the night sky, sickly green light spilling from arrow slits onto the rubble below.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 8,
      "caption": "The oracle lamp deciphers a rumor of a great beast.",
      "visual_description": "The lamp hovers over a torn poster nailed to a charred door, its flame-eye narrowed; scales and claw marks are scratched into the wood.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 9,
      "caption": "Tattered royal banners flutter above an empty plaza.",
      "visual_description": "Faded crimson banners drape from broken poles over a cracked fountain; the glass diver passes beneath them, reflected in every shard.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "Frightened faces peer from shuttered windows.",
      "visual_description": "Pale faces glimpse from behind broken shutters as Mara raises an open hand in reassurance, the lamp glowing softly beside her.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "Armored patrols march down the avenue.",
      "visual_description": "Heavy boots and pike-shafts fill the cobblestone street in silhouette; the tin fox flattens behind a barrel, blue eyes dimming.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "They find the sleeping tax collector blocking a stairway.",
      "visual_description": "A round official snores atop a marble step, head pillowed on a ledger, stamped papers stuck to his sleeves and cheek.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "Mara stamps her own forged pass to slip past.",
      "visual_description": "Mara presses a brass seal onto parchment while the official drools obliviously; the lamp tilts its flame-eye in amusement.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 14,
      "caption": "A magic door blooms with shifting runes.",
      "visual_description": "An archway of dark stone pulses with rotating glyphs of silver light; the glass diver presses a gloved palm against the surface.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "The glass diver dives through a tall mirror.",
      "visual_description": "The diver plunges headfirst into a rippling mirror set in a ruined hall, coat trailing reflected lanterns like underwater stars.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "They emerge with the captive in a hidden vault.",
      "visual_description": "Inside a vaulted chamber lit by the lamp, the diver helps a freed captive to stand while the tin fox keeps watch at the door.",
      "characters": ["glass_diver", "oracle_lamp", "tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 17,
      "caption": "The team races toward the long stone bridge.",
      "visual_description": "A narrow bridge stretches over a misty chasm, torches flaring behind; Mara leads, compass swinging, fox sprinting at her heels.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "They escape across the bridge at dawn.",
      "visual_description": "Pink light breaks over the ruined skyline behind them as the companions cross the far end of the bridge, the lamp's eye finally closing.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    }
  ]
}

